#include <queue>
#include <vector>
#include <iostream>

int main() {
    // Max-heap (default): largest element has highest priority
    std::priority_queue<int> maxHeap;
    maxHeap.push(30);
    maxHeap.push(10);
    maxHeap.push(50);
    maxHeap.push(20);

    std::cout << "Max-heap top: " << maxHeap.top() << std::endl; // 50
    maxHeap.pop();
    std::cout << "After pop: " << maxHeap.top() << std::endl;    // 30

    // Min-heap: smallest element has highest priority
    std::priority_queue<int, std::vector<int>, std::greater<int>> minHeap;
    minHeap.push(30);
    minHeap.push(10);
    minHeap.push(50);

    std::cout << "Min-heap top: " << minHeap.top() << std::endl; // 10
}
